def sc(place,time,present,why,pov,want,obst,value,oc,cc,turn,mode,exit,surf,real):
    return dict(place=place,time=time,present=present,why_now=why,pov=pov,want=want,obstacle_want=obst,value=value,
      open_charge=oc,close_charge=cc,turn=turn,exit=exit,surface_topic=surf,real_subject=real,mode=mode)
def seg(i,beat,purpose,period,fn,turn,stakes,shift,need,share,opens=None,closes=None,scene=None):
    d={"function":fn,"turn":turn,"stakes":stakes,"shift":shift,"need":need,"claim_share":share}
    if opens: d["opens"]=opens
    if closes: d["closes"]=closes
    s={"id":f"S{i:02d}","beat":beat,"light_beat":i,"purpose":purpose,"period":period,"drama":d}
    if scene: s["scene"]=scene
    return s
